import { sql } from 'drizzle-orm';
import {
  index,
  integer,
  primaryKey,
  real,
  sqliteTable,
  text,
  uniqueIndex,
} from 'drizzle-orm/sqlite-core';

/**
 * Anonymous participant. Never stores names; the code-to-person mapping lives
 * outside this system.
 */
export const participants = sqliteTable('participants', {
  code: text('code').primaryKey(),
  createdAt: text('created_at')
    .notNull()
    .default(sql`(strftime('%Y-%m-%dT%H:%M:%fZ','now'))`),
});

/**
 * One VR session. `clientId` is generated by the headset and is the
 * idempotency key: a replayed upload never duplicates a row.
 *
 * `caseId` is plain context. Unity owns the case catalog and the assignment,
 * so there is no foreign key here.
 */
export const sessions = sqliteTable(
  'sessions',
  {
    id: integer('id').primaryKey({ autoIncrement: true }),
    clientId: text('client_id').notNull(),
    participantCode: text('participant_code')
      .notNull()
      .references(() => participants.code),
    phase: text('phase').notNull(),
    caseId: text('case_id').notNull(),
    status: text('status').notNull(),
    incompleteReason: text('incomplete_reason'),
    startedAt: text('started_at').notNull(),
    finishedAt: text('finished_at'),
    durationMs: integer('duration_ms'),
    appVersion: text('app_version').notNull(),
    deviceModel: text('device_model').notNull(),
    deviceOsVersion: text('device_os_version').notNull(),
    contractVersion: text('contract_version').notNull(),
    eventCount: integer('event_count').notNull().default(0),
    invalidEventCount: integer('invalid_event_count').notNull().default(0),
    receivedAt: text('received_at')
      .notNull()
      .default(sql`(strftime('%Y-%m-%dT%H:%M:%fZ','now'))`),
  },
  (t) => [
    uniqueIndex('sessions_client_id_idx').on(t.clientId),
    index('sessions_participant_idx').on(t.participantCode),
    index('sessions_started_idx').on(t.startedAt),
  ],
);

/** Atomic recorded action. Append-only: never updated or deleted. */
export const events = sqliteTable(
  'events',
  {
    sessionId: integer('session_id')
      .notNull()
      .references(() => sessions.id, { onDelete: 'cascade' }),
    eventId: integer('event_id').notNull(),
    occurredAt: text('occurred_at').notNull(),
    scene: text('scene').notNull(),
    procedure: text('procedure').notNull(),
    action: text('action').notNull(),
    object: text('object'),
    // JSON keeps the original type: a recorded pulse of 76 stays a number,
    // not the string "76". Typed metrics depend on it.
    value: text('value', { mode: 'json' }),
    outcome: text('outcome').notNull(),
    context: text('context', { mode: 'json' }),
  },
  (t) => [
    primaryKey({ columns: [t.sessionId, t.eventId] }),
    index('events_session_procedure_idx').on(t.sessionId, t.procedure),
  ],
);

/** Lines that failed validation. Kept so nothing is silently discarded. */
export const invalidEvents = sqliteTable(
  'invalid_events',
  {
    id: integer('id').primaryKey({ autoIncrement: true }),
    sessionId: integer('session_id')
      .notNull()
      .references(() => sessions.id, { onDelete: 'cascade' }),
    line: integer('line').notNull(),
    reason: text('reason').notNull(),
    raw: text('raw').notNull(),
  },
  (t) => [index('invalid_events_session_idx').on(t.sessionId)],
);

/**
 * Calculated metrics. Derived and disposable: deleting and recalculating must
 * always be safe.
 *
 * `configVersion` records which `study_config` produced this result, and
 * `approved` mirrors whether that configuration was clinically approved.
 */
export const metricResults = sqliteTable(
  'metric_results',
  {
    id: integer('id').primaryKey({ autoIncrement: true }),
    sessionId: integer('session_id')
      .notNull()
      .references(() => sessions.id, { onDelete: 'cascade' }),
    indicator: text('indicator').notNull(),
    metric: text('metric').notNull(),
    valueType: text('value_type').notNull(),
    valueBool: integer('value_bool', { mode: 'boolean' }),
    valueNumber: real('value_number'),
    valueText: text('value_text'),
    notEvaluableReason: text('not_evaluable_reason'),
    configVersion: integer('config_version').notNull(),
    approved: integer('approved', { mode: 'boolean' }).notNull().default(false),
    computedAt: text('computed_at')
      .notNull()
      .default(sql`(strftime('%Y-%m-%dT%H:%M:%fZ','now'))`),
  },
  (t) => [uniqueIndex('metric_results_unique_idx').on(t.sessionId, t.indicator, t.metric)],
);

/**
 * Clinical parameters for metric calculation.
 *
 * Values ship unapproved (`approved = false`) so the dashboard can show real
 * output while the psychologist reviews them. The flag is what prevents a
 * provisional number from being mistaken for an approved criterion.
 */
export const studyConfig = sqliteTable('study_config', {
  key: text('key').primaryKey(),
  value: text('value', { mode: 'json' }).notNull(),
  approved: integer('approved', { mode: 'boolean' }).notNull().default(false),
  description: text('description').notNull(),
  version: integer('version').notNull().default(1),
  updatedAt: text('updated_at')
    .notNull()
    .default(sql`(strftime('%Y-%m-%dT%H:%M:%fZ','now'))`),
});

/** Dashboard accounts. Login lives in the app, no external proxy. */
export const users = sqliteTable(
  'users',
  {
    id: integer('id').primaryKey({ autoIncrement: true }),
    username: text('username').notNull(),
    passwordHash: text('password_hash').notNull(),
    displayName: text('display_name').notNull(),
    createdAt: text('created_at')
      .notNull()
      .default(sql`(strftime('%Y-%m-%dT%H:%M:%fZ','now'))`),
  },
  (t) => [uniqueIndex('users_username_idx').on(t.username)],
);
